js.text:

function grid$s41Close(f){
  this.constructor(f);
}
grid$s41Close.prototype = new DirEvent();
grid$s41Close.prototype.afterInit = function(renderType){
  var p = this._dir;
  if (p.options._status == -1) p.find(".toolbar-close").attr('title', p.msg('close'))
  else p.find(".toolbar-close").attr('title', p.msg('unclose'))
}
grid$s41Close.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir, g = p.grid(gindex), dt = g.data;
  switch (id) {
    case 'close':
      var fees = p.selectedItems(), xstatus = p.options._status, msg = (xstatus == -1)? p.msg('msg1'): p.msg('msg2');
      if (fees.count() > 0)
        $.question(msg, $.msg.get("QuestionTitle"), p, function (q, v) {
          q._close();
          if (v){
            p.request('CloseDH', '', [["tblKeys", "T", fees.sqlval()], ['xstatus', 'I', xstatus]], function(pp, d, run){
              if (run) {
                p._refresh();
                p.clearSelectedItems();
              }
            });
          }
        });
      return false;
      break;
    default:
      break;
  }
  return true;
}

